// src/lib/plattform/sitzung.js
//
// Signierte Sitzungstoken (HMAC-SHA256 über SESSION_SECRET) – nur Web Crypto,
// damit dieselbe Prüfung in der Middleware (Edge) und in Route-Handlern läuft.
//
// Token:  v1.<payload base64url>.<signatur base64url>
// Payload { u: Nutzer-ID, v: Sitzungsversion, iat, exp } – enthält keine Rollen:
// Rollen und Sperren werden bei jeder Anfrage frisch aus dem Backend gelesen.
// Erhöht sich die Sitzungsversion eines Kontos (Passwort geändert/zurückgesetzt,
// Konto gesperrt), sind alle alten Token sofort ungültig.

export const SITZUNG_DAUER_S = 60 * 60 * 24 * 7; // 7 Tage

const DEV_GEHEIMNIS = "oekoinvest-entwicklung-unsicher-nie-produktiv-verwenden";
const enc = new TextEncoder();
const dec = new TextDecoder();

/** Cookie-Name: in Produktion mit __Host--Präfix (erzwingt Secure, Path=/, keine Domain) */
export function cookieName() {
  return process.env.NODE_ENV === "production" ? "__Host-oi_sitzung" : "oi_sitzung";
}

function geheimnis() {
  const s = process.env.SESSION_SECRET || "";
  if (process.env.NODE_ENV === "production") {
    if (s.length < 32) throw new Error("SESSION_SECRET fehlt oder ist kürzer als 32 Zeichen – in Produktion Pflicht.");
    return s;
  }
  if (s) return s;
  if (!globalThis.__oiSitzungGewarnt) {
    globalThis.__oiSitzungGewarnt = true;
    console.warn("[plattform] SESSION_SECRET nicht gesetzt – unsicherer Entwicklungs-Schlüssel aktiv. Niemals so produktiv betreiben.");
  }
  return DEV_GEHEIMNIS;
}

const schluesselCache = new Map();
function schluessel() {
  const s = geheimnis();
  if (!schluesselCache.has(s)) {
    schluesselCache.set(s, crypto.subtle.importKey("raw", enc.encode(s), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]));
  }
  return schluesselCache.get(s);
}

function b64u(bytes) {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let bin = "";
  for (let i = 0; i < arr.length; i++) bin += String.fromCharCode(arr[i]);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function vonB64u(s) {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64 + "=".repeat((4 - (b64.length % 4)) % 4));
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

/** sitzungId: Kennung des Sitzungseintrags im Backend (Sitzungsliste, einzeln widerrufbar) */
export async function tokenErstellen({ nutzerId, version = 0, sitzungId = null }) {
  const jetzt = Math.floor(Date.now() / 1000);
  const payload = b64u(enc.encode(JSON.stringify({ u: nutzerId, v: version, ...(sitzungId ? { s: sitzungId } : {}), iat: jetzt, exp: jetzt + SITZUNG_DAUER_S })));
  const daten = `v1.${payload}`;
  const sig = await crypto.subtle.sign("HMAC", await schluessel(), enc.encode(daten));
  return `${daten}.${b64u(sig)}`;
}

/** Liefert { nutzerId, version, sitzungId, exp } oder null. Signaturprüfung zeitkonstant (subtle.verify). */
export async function tokenPruefen(token) {
  try {
    if (typeof token !== "string" || token.length > 600) return null;
    const teile = token.split(".");
    if (teile.length !== 3 || teile[0] !== "v1") return null;
    const ok = await crypto.subtle.verify("HMAC", await schluessel(), vonB64u(teile[2]), enc.encode(`${teile[0]}.${teile[1]}`));
    if (!ok) return null;
    const p = JSON.parse(dec.decode(vonB64u(teile[1])));
    if (!p?.u || typeof p.exp !== "number" || p.exp < Math.floor(Date.now() / 1000)) return null;
    return { nutzerId: String(p.u), version: Number(p.v) || 0, sitzungId: typeof p.s === "string" ? p.s : null, exp: p.exp };
  } catch {
    return null;
  }
}

/** Cookie-Optionen (HttpOnly, SameSite=Lax, Secure in Produktion) */
export function cookieOptionen(maxAge = SITZUNG_DAUER_S) {
  return { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge };
}

// ---------------------------------------------------------------- Zwischenschritt Zwei-Faktor (Login, Sicherheit & Teams)
// Nach Passwort bzw. E-Mail-Link, aber vor dem 2FA-Code: kurzlebiges, signiertes Token (5 min) in eigenem
// Cookie. Es berechtigt zu nichts außer dem Absenden des Codes (POST /api/auth/zwei-faktor).
// Eigene Domäne im signierten Text („z1.“), damit es nie als Sitzungstoken durchgeht.

export const ZWISCHEN_DAUER_S = 5 * 60;

export async function zwischenTokenErstellen({ nutzerId, version = 0, methode = "passwort" }) {
  const jetzt = Math.floor(Date.now() / 1000);
  const payload = b64u(enc.encode(JSON.stringify({ u: nutzerId, v: version, m: methode, iat: jetzt, exp: jetzt + ZWISCHEN_DAUER_S })));
  const daten = `z1.${payload}`;
  const sig = await crypto.subtle.sign("HMAC", await schluessel(), enc.encode(daten));
  return `${daten}.${b64u(sig)}`;
}

/** Liefert { nutzerId, version, methode, iat } oder null */
export async function zwischenTokenPruefen(token) {
  try {
    if (typeof token !== "string" || token.length > 600) return null;
    const teile = token.split(".");
    if (teile.length !== 3 || teile[0] !== "z1") return null;
    const ok = await crypto.subtle.verify("HMAC", await schluessel(), vonB64u(teile[2]), enc.encode(`${teile[0]}.${teile[1]}`));
    if (!ok) return null;
    const p = JSON.parse(dec.decode(vonB64u(teile[1])));
    if (!p?.u || typeof p.exp !== "number" || p.exp < Math.floor(Date.now() / 1000)) return null;
    return { nutzerId: String(p.u), version: Number(p.v) || 0, methode: String(p.m || "passwort"), iat: p.iat };
  } catch {
    return null;
  }
}
// src/lib/plattform/demoGuard.js
//
// Demo-Guard (Masterplan Abschnitt 3, S0 Nr. 8; Paket A): Das Demo-Backend zeigt auf /login alle
// Demo-Konten einschließlich Backoffice-Admin mit Passwort an. Läuft ein Produktions-Build mit
// PLATTFORM_DEMO=1 unter der echten Domain, wäre das eine vollständige Übernahme. Deshalb gilt im
// Produktions-Build (NODE_ENV=production):
//   - Demo nur mit PLATTFORM_DEMO=1 (wie bisher),
//   - UND nur, wenn PLATTFORM_BASIS_URL bzw. NEXT_PUBLIC_SITE_URL gesetzt ist (ohne Wert fällt
//     SITE.url auf die Produktionsdomain zurück – also sperren: fail-closed),
//   - UND keine dieser URLs auf die Produktionsdomain zeigt (PRODUKTIV_HOSTS).
// Entwicklung (next dev) bleibt unverändert.
//
// Ohne Importe, damit `node --test` die Datei direkt laden kann.
// Test: node --test src/lib/plattform/demoGuard.test.mjs

/** Hosts der Produktivseite (Entscheidung des Inhabers: Domain oekoinvest.com). */
export const PRODUKTIV_HOSTS = ["oekoinvest.com", "www.oekoinvest.com"];

/**
 * Darf das Demo-Backend in dieser Umgebung laufen?
 * @param {Record<string,string|undefined>} [env]
 * @returns {{ erlaubt: boolean, grund: string }}
 */
export function demoPruefung(env = process.env) {
  if (env.NODE_ENV !== "production") return { erlaubt: true, grund: "entwicklung" };
  if (env.PLATTFORM_DEMO !== "1") return { erlaubt: false, grund: "PLATTFORM_DEMO nicht gesetzt" };
  const urls = [env.PLATTFORM_BASIS_URL, env.NEXT_PUBLIC_SITE_URL].map((u) => String(u || "").trim()).filter(Boolean);
  if (!urls.length) return { erlaubt: false, grund: "keine Basis-URL gesetzt (Rückfall auf Produktionsdomain)" };
  for (const u of urls) {
    let host;
    try {
      host = new URL(u).hostname.toLowerCase().replace(/\.$/, "");
    } catch {
      return { erlaubt: false, grund: `ungültige URL ${u}` };
    }
    if (PRODUKTIV_HOSTS.includes(host)) return { erlaubt: false, grund: `Produktionsdomain ${host}` };
  }
  return { erlaubt: true, grund: "vorführung" };
}

export const demoErlaubt = (env = process.env) => demoPruefung(env).erlaubt;
// src/lib/plattform/hashkette.js
//
// Revisionssicheres Aktivitätsprotokoll: Hash-Kette über alle Einträge.
//
//   hash_n = SHA-256( prevHash_n + "\n" + inhalt_n )      mit prevHash_n = hash_(n-1)
//
// `inhalt` ist eine kanonische JSON-Darstellung der fachlichen Felder in fester Reihenfolge
// (id, am, nutzerId, aktion, objektArt, objektId, text, ip). Wer einen Eintrag nachträglich ändert,
// löscht, einfügt oder umsortiert, bricht die Kette ab dieser Stelle – verifyChain() meldet die
// erste Abweichung. Identisches Verfahren in Frappe: plattform/hashkette.py (Feld prev_hash/entry_hash).
//
// Werden alte Einträge archiviert (Demo: > 5000 Einträge), bleibt ein Anker { hash, anzahl, bis }
// stehen: die Prüfung beginnt dann beim Anker-Hash statt beim Startwert.
//
// Nur serverseitig (node:crypto).

import { createHash } from "node:crypto";

export const KETTE_START = "0".repeat(64);
export const KETTE_FELDER = ["id", "am", "nutzerId", "aktion", "objektArt", "objektId", "text", "ip"];

const wert = (v) => (v === undefined || v === null ? "" : String(v));

/** Kanonischer Inhalt eines Eintrags (unabhängig von zusätzlichen Feldern wie `nutzer`) */
export function eintragInhalt(e) {
  return JSON.stringify(KETTE_FELDER.map((k) => [k, wert(e?.[k])]));
}

export function eintragHash(prevHash, e) {
  return createHash("sha256").update(`${prevHash}\n${eintragInhalt(e)}`, "utf8").digest("hex");
}

/** Eintrag an die Kette anhängen: setzt prevHash und hash (verändert das Objekt) */
export function verketten(e, prevHash = KETTE_START) {
  e.prevHash = prevHash || KETTE_START;
  e.hash = eintragHash(e.prevHash, e);
  return e;
}

/**
 * Kette prüfen. `eintraege` in Einfügereihenfolge (älteste zuerst).
 * Liefert { ok, geprueft, fehler: [{ index, id, grund }], letzterHash, start }.
 * Mit `alleFehler: false` (Standard) endet die Prüfung beim ersten Bruch.
 */
export function verifyChain(eintraege = [], { anker = null, alleFehler = false } = {}) {
  const start = anker?.hash || KETTE_START;
  let prev = start;
  const fehler = [];
  let geprueft = 0;
  for (let i = 0; i < eintraege.length; i++) {
    const e = eintraege[i];
    geprueft++;
    let grund = "";
    if (!e?.hash) grund = "Eintrag ohne Hash (ungesichert eingefügt)";
    else if (e.prevHash !== prev) grund = "Verweis auf den Vorgänger passt nicht (Eintrag gelöscht, eingefügt oder umsortiert)";
    else if (eintragHash(prev, e) !== e.hash) grund = "Inhalt wurde nachträglich verändert";
    if (grund) {
      fehler.push({ index: i, id: e?.id || null, am: e?.am || null, grund });
      if (!alleFehler) break;
    }
    prev = e?.hash || prev;
  }
  return { ok: fehler.length === 0, geprueft, anzahl: eintraege.length, fehler, letzterHash: prev, start };
}

/** Python-Name wie in Frappe (plattform/hashkette.py) */
export const verify_chain = verifyChain;

