// src/lib/plattform/server/route.js
//
// Gemeinsamer Rahmen aller Plattform-APIs:
//  - CSRF-Schutz: Mutationen nur mit passendem Origin-Header UND Content-Type JSON
//    (Uploads: multipart + Kopfzeile X-Plattform-Upload). Ein fremdes Formular kann weder
//    JSON senden noch eigene Kopfzeilen setzen; fremde fetch-Aufrufe scheitern am Origin.
//  - Sitzung aus dem signierten Cookie, Nutzer frisch aus dem Backend (Rollen, Sperre, Version)
//  - Rollenprüfung vorab (Eigentum prüft das Backend)
//  - Rate-Limits, Größenbegrenzung des Bodys
//  - Fehler → { ok:false, error, code } mit passendem HTTP-Status, Interna nur ins Log

import { NextResponse } from "next/server";
import { backend } from "../backend";
import { PlattformFehler } from "../fehler";
import { cookieName, cookieOptionen, tokenErstellen, tokenPruefen } from "../sitzung";
import { ipAdresse } from "@/lib/ipAdresse";
import { SITE } from "@/data/site";
import { grenze, rateLimit } from "./rateLimit";
import { adminRechtPruefen } from "./rechte"; // Backoffice-Unterrollen (Rechte-Matrix)

const KEIN_CACHE = { "Cache-Control": "no-store" };

export function antwort(daten, status = 200) {
  return NextResponse.json(daten, { status, headers: KEIN_CACHE });
}

export function fehlerAntwort(e) {
  if (e instanceof PlattformFehler) {
    return antwort({ ok: false, error: e.message, code: e.code }, e.status);
  }
  console.error("[plattform] Unerwarteter Fehler:", e);
  return antwort({ ok: false, error: "Es ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.", code: "fehler" }, 500);
}

function hostVon(url) {
  try {
    return new URL(url).host.toLowerCase();
  } catch {
    return "";
  }
}

/** Erlaubte Hosts für den Origin-Abgleich */
function erlaubteHosts(request) {
  const hosts = new Set();
  const h = request.headers.get("x-forwarded-host") || request.headers.get("host");
  if (h) hosts.add(h.split(",")[0].trim().toLowerCase());
  hosts.add(hostVon(SITE.url));
  for (const o of String(process.env.PLATTFORM_ORIGINS || "").split(",")) if (o.trim()) hosts.add(hostVon(o.trim()));
  return hosts;
}

/** CSRF: Origin muss zur eigenen Seite gehören */
export function herkunftPruefen(request) {
  const origin = request.headers.get("origin");
  if (!origin || origin === "null" || !erlaubteHosts(request).has(hostVon(origin))) {
    throw new PlattformFehler(403, "Anfrage von fremder Herkunft abgelehnt.", "herkunft");
  }
}

/** JSON-Body lesen (max. Bytes), muss ein Objekt sein */
export async function jsonLesen(request, maxBytes = 64 * 1024) {
  const typ = request.headers.get("content-type") || "";
  if (!typ.toLowerCase().startsWith("application/json")) throw new PlattformFehler(415, "Erwartet wird JSON.");
  const laenge = Number(request.headers.get("content-length") || 0);
  if (laenge > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
  const text = await request.text();
  if (text.length > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
  let daten;
  try {
    daten = text ? JSON.parse(text) : {};
  } catch {
    throw new PlattformFehler(400, "Ungültiges JSON.");
  }
  if (!daten || typeof daten !== "object" || Array.isArray(daten)) throw new PlattformFehler(400, "Ungültige Daten.");
  return daten;
}

/** Angemeldeten Nutzer aus dem Cookie lesen (oder null) */
export async function nutzerAusAnfrage(request, b = backend()) {
  const token = request.cookies.get(cookieName())?.value;
  if (!token) return null;
  const s = await tokenPruefen(token);
  if (!s) return null;
  // sitzungId: Sitzungseintrag muss bestehen (einzeln widerrufbar, siehe backend/demo/sicherheit.js)
  const u = await b.nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId });
  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
  return u;
}

/** Sitzungscookie setzen (sitzungId aus sitzungAnlegen – Anmeldung läuft über server/anmeldung.js) */
export async function sitzungSetzen(res, nutzer, { sitzungId = null } = {}) {
  const token = await tokenErstellen({ nutzerId: nutzer.id, version: nutzer.sitzungVersion || 0, sitzungId: sitzungId || nutzer.sitzung?.id || null });
  res.cookies.set(cookieName(), token, cookieOptionen());
  return res;
}

export function sitzungLoeschen(res) {
  res.cookies.set(cookieName(), "", { ...cookieOptionen(0), maxAge: 0 });
  return res;
}

/** Basis-URL für Links in E-Mails: in Produktion fest (kein Host-Header-Vertrauen) */
export function basisUrl(request) {
  if (process.env.NODE_ENV === "production") return (process.env.PLATTFORM_BASIS_URL || SITE.url).replace(/\/$/, "");
  return request.nextUrl.origin;
}

/** Nutzer für die Antwort an den Browser (ohne interne Felder) */
export function nutzerFuerBrowser(u) {
  if (!u) return null;
  return { id: u.id, email: u.email, vorname: u.vorname, nachname: u.nachname, firma: u.firma, telefon: u.telefon, rollen: u.rollen, emailBestaetigt: !!u.emailBestaetigt, suchprofil: u.suchprofil || null, mailEinstellungen: u.mailEinstellungen || null, backofficeRollen: u.backofficeRollen || null,
    // Login, Sicherheit & Teams: Komfort (Avatarfarbe, Sprache), Organisationskontext, 2FA-Status
    komfort: u.komfort || null, organisation: u.organisation || null, organisationen: u.organisationen || [], zweiFaktorAktiv: !!u.zweiFaktorAktiv, zweiFaktorPflichtOffen: !!u.zweiFaktorPflichtOffen };
}

/**
 * Route-Handler mit Rahmen.
 *
 * optionen:
 *   auth      true (Pflicht, Standard) | "optional" | false
 *   rollen    [..] – mindestens eine davon (admin darf immer)
 *   admin     true – nur Rolle admin
 *   limit     Name aus GRENZEN (je IP)
 *   json      true – JSON-Body lesen (Standard bei POST/PATCH/PUT/DELETE)
 *   upload    true – multipart statt JSON (eigene Kopfzeile Pflicht)
 *   maxBytes  Größe des JSON-Bodys
 *   ohne2fa   true – auch erreichbar, solange eine Pflicht-2FA noch nicht eingerichtet ist (Sicherheits-APIs)
 */
export function route(optionen, handler) {
  const o = { auth: true, ...optionen };
  return async (request, ctx) => {
    try {
      const mutation = !["GET", "HEAD", "OPTIONS"].includes(request.method);
      const params = ctx?.params ? await ctx.params : {};
      const ip = ipAdresse(request);

      if (mutation) {
        herkunftPruefen(request);
        if (o.upload && request.headers.get("x-plattform-upload") !== "1") throw new PlattformFehler(403, "Upload nur über das Portal.", "herkunft");
      }
      if (o.limit) rateLimit(`${o.limit}:${ip || "ohne-ip"}`, ...grenze(o.limit));

      const b = backend();
      let nutzer = null;
      if (o.auth) {
        nutzer = await nutzerAusAnfrage(request, b);
        if (!nutzer && o.auth === true) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
        if (nutzer) {
          const admin = nutzer.rollen?.includes("admin");
          if (o.admin && !admin) throw new PlattformFehler(403, "Nur für das Backoffice.");
          if (o.rollen && !admin && !o.rollen.some((r) => nutzer.rollen?.includes(r))) {
            throw new PlattformFehler(403, "Dafür fehlt Ihnen die passende Rolle.");
          }
          // Pflicht-2FA (Rolle, z. B. Backoffice): bis zur Einrichtung nur Sicherheits-APIs
          if (nutzer.zweiFaktorPflichtOffen && !o.ohne2fa && o.auth === true) {
            throw new PlattformFehler(403, "Für Ihr Konto ist die Zwei-Faktor-Anmeldung Pflicht. Bitte richten Sie sie unter „Sicherheit“ ein.", "zwei_faktor_pflicht");
          }
        }
      }

      const body = mutation && !o.upload && o.json !== false ? await jsonLesen(request, o.maxBytes) : undefined;
      if (nutzer) adminRechtPruefen(nutzer, { request, body, params, recht: o.recht }); // feine Backoffice-Rechte für /api/admin/**
      const ergebnis = await handler({ request, params, nutzer, body, backend: b, ip, suche: request.nextUrl.searchParams });
      if (ergebnis instanceof Response) return ergebnis;
      return antwort(ergebnis === undefined ? { ok: true } : ergebnis);
    } catch (e) {
      return fehlerAntwort(e);
    }
  };
}

// src/lib/plattform/server/rateLimit.js
//
// Einfaches Rate-Limit im Arbeitsspeicher (gleitendes Fenster je Schlüssel).
// Reicht für einen einzelnen Node-Prozess; bei mehreren Instanzen zusätzlich
// am Reverse-Proxy (nginx limit_req) begrenzen – siehe docs/PLATTFORM.md.

import { PlattformFehler } from "../fehler";

const speicher = (globalThis.__oiRateLimit ||= new Map());

/** Wirft 429, wenn `schluessel` mehr als `max` Treffer im Fenster hat */
export function rateLimit(schluessel, max, fensterMs) {
  const jetzt = Date.now();
  const liste = (speicher.get(schluessel) || []).filter((t) => jetzt - t < fensterMs);
  if (liste.length >= max) {
    speicher.set(schluessel, liste);
    throw new PlattformFehler(429, "Zu viele Versuche in kurzer Zeit – bitte warten Sie einige Minuten.");
  }
  liste.push(jetzt);
  speicher.set(schluessel, liste);

  // gelegentlich aufräumen
  if (speicher.size > 5000) {
    for (const [k, v] of speicher) if (!v.length || jetzt - v[v.length - 1] > 3600e3) speicher.delete(k);
  }
}

/** Grenzen je Aktion: [max, Fenster in ms] */
export const GRENZEN = {
  login: [10, 15 * 60e3],
  loginEmail: [8, 15 * 60e3],
  registrieren: [5, 60 * 60e3],
  anfrage: [10, 60 * 60e3],
  passwort: [5, 60 * 60e3],
  upload: [60, 60 * 60e3],
  nachricht: [120, 60 * 60e3],
  // Login, Sicherheit & Teams
  magicLink: [5, 60 * 60e3],
  zweiFaktor: [10, 15 * 60e3],
  einladung: [30, 60 * 60e3],
  export: [10, 60 * 60e3],
};

/**
 * In der Entwicklung sind die Grenzen 10-fach gelockert (wiederholte Testläufe),
 * über PLATTFORM_RATE_FAKTOR einstellbar. In Produktion gilt immer Faktor 1.
 */
export function grenze(name) {
  const [max, fenster] = GRENZEN[name];
  const faktor = process.env.NODE_ENV !== "production" ? Number(process.env.PLATTFORM_RATE_FAKTOR) || 10 : 1;
  return [Math.max(1, Math.round(max * faktor)), fenster];
}
// src/lib/plattform/server/passwort.js
//
// Passwort-Hashing für das Demo-Backend: scrypt mit 16 Byte Salt, Vergleich
// zeitkonstant. Format: scrypt$N$r$p$<salt b64>$<hash b64> (Parameter im Hash,
// damit sie später erhöht werden können). Frappe nutzt sein eigenes Verfahren.

import { randomBytes, scrypt, timingSafeEqual } from "node:crypto";

const N = 16384;
const R = 8;
const P = 1;
const LAENGE = 64;

function scryptAsync(passwort, salt, n, r, p) {
  return new Promise((resolve, reject) =>
    scrypt(passwort.normalize("NFKC"), salt, LAENGE, { N: n, r, p, maxmem: 64 * 1024 * 1024 }, (err, key) => (err ? reject(err) : resolve(key)))
  );
}

export async function passwortHash(passwort) {
  const salt = randomBytes(16);
  const key = await scryptAsync(String(passwort), salt, N, R, P);
  return `scrypt$${N}$${R}$${P}$${salt.toString("base64")}$${key.toString("base64")}`;
}

// Für unbekannte E-Mail-Adressen trotzdem rechnen – gleiche Antwortzeit (keine Konto-Enumeration)
let attrappe = null;

export async function passwortPruefen(passwort, gespeichert) {
  if (!gespeichert) {
    attrappe ||= await passwortHash("attrappe-ohne-konto");
    gespeichert = attrappe;
    passwort = `${passwort}-x`;
  }
  const teile = String(gespeichert).split("$");
  if (teile.length !== 6 || teile[0] !== "scrypt") return false;
  const [, n, r, p, salt, hash] = teile;
  const soll = Buffer.from(hash, "base64");
  const ist = await scryptAsync(String(passwort ?? ""), Buffer.from(salt, "base64"), Number(n), Number(r), Number(p));
  return soll.length === ist.length && timingSafeEqual(soll, ist);
}
// src/lib/plattform/server/leak.js
//
// Optionale Leak-Prüfung neuer Passwörter gegen „Have I Been Pwned“ (Pwned Passwords, k-Anonymity):
// Nur die ersten 5 Zeichen des SHA-1-Hashes verlassen den Server, der Abgleich des Rests erfolgt lokal.
// „Add-Padding“ verschleiert zusätzlich die Antwortgröße. Aktiv nur mit PLATTFORM_HIBP=1.
// Bei Netzfehlern/Zeitüberschreitung wird die Prüfung übersprungen (kein Ausfall der Registrierung).

import { createHash } from "node:crypto";
import { PlattformFehler } from "../fehler";

const URL_BASIS = "https://api.pwnedpasswords.com/range/";
const TIMEOUT_MS = 3000;

export const leakPruefungAktiv = () => process.env.PLATTFORM_HIBP === "1";

/** Anzahl der bekannten Vorkommen (0 = nicht bekannt) oder null, wenn nicht geprüft */
export async function passwortVorkommen(passwort) {
  if (!leakPruefungAktiv() || typeof passwort !== "string" || !passwort) return null;
  const sha1 = createHash("sha1").update(passwort, "utf8").digest("hex").toUpperCase();
  const praefix = sha1.slice(0, 5);
  const rest = sha1.slice(5);
  try {
    const res = await fetch(URL_BASIS + praefix, {
      headers: { "Add-Padding": "true", "User-Agent": "OekoInvest-Plattform" },
      cache: "no-store",
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    if (!res.ok) return null;
    const text = await res.text();
    for (const zeile of text.split(/\r?\n/)) {
      const [suffix, anzahl] = zeile.trim().split(":");
      if (suffix === rest) return Number(anzahl) || 0; // Padding-Zeilen haben Anzahl 0
    }
    return 0;
  } catch (e) {
    console.warn("[plattform] Leak-Prüfung übersprungen:", e?.name || "Fehler");
    return null;
  }
}

/** Wirft 422, wenn das Passwort in bekannten Datenlecks vorkommt (nur mit PLATTFORM_HIBP=1) */
export async function passwortLeakPruefen(passwort) {
  const n = await passwortVorkommen(passwort);
  if (n && n > 0) {
    throw new PlattformFehler(422, "Dieses Passwort ist aus bekannten Datenlecks bekannt und daher unsicher. Bitte wählen Sie ein anderes – am besten eine Passphrase aus mehreren Wörtern.", "passwort_geleakt");
  }
}

// POST /api/auth/login – { email, passwort } → Sitzungscookie
// Mit aktiver Zwei-Faktor-Anmeldung (und nicht gemerktem Gerät): { ok, zweiFaktor: true } + Zwischen-Cookie,
// die Sitzung entsteht erst nach POST /api/auth/zwei-faktor. Kontosperre mit Backoff → 429 (code „gesperrt“).
import { route } from "@/lib/plattform/server/route";
import { anfrageKontext, anmeldungFortsetzen } from "@/lib/plattform/server/anmeldung";
import { rateLimit, grenze } from "@/lib/plattform/server/rateLimit";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { email as emailPruefen } from "@/lib/plattform/validierung";

export const POST = route({ auth: false, limit: "login" }, async ({ body, backend, request, ip }) => {
  const email = emailPruefen(body.email);
  if (!email || typeof body.passwort !== "string" || !body.passwort) throw new PlattformFehler(422, "Bitte E-Mail-Adresse und Passwort eingeben.");
  rateLimit(`loginEmail:${email}`, ...grenze("loginEmail"));
  const k = anfrageKontext(request, ip);
  const nutzer = await backend.anmelden({ email, passwort: body.passwort, ip, userAgent: k.userAgent, land: k.land });
  if (!nutzer) throw new PlattformFehler(401, "E-Mail-Adresse oder Passwort ist falsch.", "login");
  return anmeldungFortsetzen({ request, ip, nutzer, methode: "passwort" });
});
// POST /api/auth/zwei-faktor – { code, merken? } zweiter Schritt der Anmeldung (Zwischen-Cookie aus Login/E-Mail-Link)
// code: 6-stelliger TOTP-Code oder Wiederherstellungscode (XXXXX-XXXXX, einmalig). merken: Gerät 30 Tage merken.
// Falsche Codes zählen zur Kontosperre (Backoff). Erfolg: neue Sitzung, { ok, nutzer, zweiFaktorMethode, codesUebrig }.
import { route } from "@/lib/plattform/server/route";
import { zweiFaktorAbschliessen } from "@/lib/plattform/server/anmeldung";

export const POST = route({ auth: false, limit: "zweiFaktor" }, async ({ body, request, ip }) =>
  zweiFaktorAbschliessen({ request, ip, code: body.code, merken: body.merken === true })
);

// src/lib/plattform/server/anmeldung.js
//
// Anmeldeablauf der Website (Login, Sicherheit & Teams) – gemeinsam für Passwort, E-Mail-Link,
// Passwort-Reset und Registrierung:
//
//   1. Erster Faktor geprüft (Backend) → anmeldungFortsetzen()
//   2. 2FA aktiv und Gerät nicht gemerkt → kurzlebiges Zwischen-Cookie (5 min, SameSite=Strict), KEINE Sitzung
//      → Browser zeigt den Code-Schritt → POST /api/auth/zwei-faktor → zweiFaktorAbschliessen()
//   3. sitzungStarten(): neuer Sitzungseintrag im Backend (Sitzungsrotation: jede Anmeldung = neue Kennung),
//      signiertes Cookie mit Sitzungskennung, Geräte-Cookie (für „neues Gerät“ und „30 Tage merken“).
//
// Nur serverseitig (Route-Handler).

import { antwort, nutzerFuerBrowser, sitzungSetzen } from "./route";
import { sicherheit } from "../backend/sicherheit";
import { cookieOptionen, zwischenTokenErstellen, zwischenTokenPruefen, ZWISCHEN_DAUER_S } from "../sitzung";
import { PlattformFehler } from "../fehler";

const PROD = () => process.env.NODE_ENV === "production";
export const zwischenCookieName = () => (PROD() ? "__Host-oi_2fa" : "oi_2fa");
export const geraetCookieName = () => (PROD() ? "__Host-oi_geraet" : "oi_geraet");
const GERAET_MAX_S = 400 * 86400; // Obergrenze der Browser für Cookie-Laufzeiten

/** Kontext der Anfrage für Historie/Geräte: IP, User-Agent, Land (nur wenn ein Proxy es liefert) */
export function anfrageKontext(request, ip = "") {
  return {
    ip,
    userAgent: (request.headers.get("user-agent") || "").slice(0, 400),
    land: (request.headers.get("cf-ipcountry") || request.headers.get("x-vercel-ip-country") || "").slice(0, 2).toUpperCase(),
    geraetToken: request.cookies.get(geraetCookieName())?.value || "",
  };
}

function zwischenLoeschen(res) {
  res.cookies.set(zwischenCookieName(), "", { ...cookieOptionen(0), sameSite: "strict", maxAge: 0 });
  return res;
}

/**
 * Sitzung anlegen und Cookies setzen. `daten` wird der JSON-Antwort hinzugefügt.
 * ersetzt: Kennung der bisherigen Sitzung (Rotation nach 2FA-Einrichtung o. Ä.).
 */
export async function sitzungStarten({ request, ip, nutzer, methode, zweiFaktor = false, geraetMerken = false, ersetzt = null, daten = {}, status = 200 }) {
  const k = anfrageKontext(request, ip);
  const r = await sicherheit().sitzungAnlegen(nutzer, { ...k, methode, zweiFaktor, geraetMerken, ersetzt });
  const res = antwort({ ok: true, nutzer: nutzerFuerBrowser(nutzer), ...daten }, status);
  await sitzungSetzen(res, nutzer, { sitzungId: r.sitzung.id });
  if (r.geraetToken) {
    res.cookies.set(geraetCookieName(), r.geraetToken, { httpOnly: true, sameSite: "lax", secure: PROD(), path: "/", maxAge: GERAET_MAX_S });
  }
  return zwischenLoeschen(res);
}

/**
 * Nach dem ersten Faktor: bei aktiver 2FA (und nicht gemerktem Gerät) Zwischenschritt, sonst Sitzung.
 * Antwort im Zwischenschritt: { ok: true, zweiFaktor: true } – ohne Nutzerdaten.
 */
export async function anmeldungFortsetzen({ request, ip, nutzer, methode, daten = {}, status = 200 }) {
  if (nutzer?.zweiFaktorAktiv) {
    const { geraetToken } = anfrageKontext(request, ip);
    const vertraut = geraetToken ? await sicherheit().geraetVertraut({ nutzerId: nutzer.id, geraetToken }) : false;
    if (!vertraut) {
      const res = antwort({ ok: true, zweiFaktor: true, methode });
      const token = await zwischenTokenErstellen({ nutzerId: nutzer.id, version: nutzer.sitzungVersion || 0, methode });
      res.cookies.set(zwischenCookieName(), token, { ...cookieOptionen(ZWISCHEN_DAUER_S), sameSite: "strict" });
      return res;
    }
    return sitzungStarten({ request, ip, nutzer, methode: `${methode} (Gerät gemerkt)`, zweiFaktor: true, daten, status });
  }
  return sitzungStarten({ request, ip, nutzer, methode, daten, status });
}

/** Zweiter Schritt: Code prüfen (Backend zählt Fehlversuche zur Kontosperre), dann Sitzung */
export async function zweiFaktorAbschliessen({ request, ip, code, merken = false }) {
  const z = await zwischenTokenPruefen(request.cookies.get(zwischenCookieName())?.value);
  if (!z) throw new PlattformFehler(401, "Die Anmeldung ist abgelaufen. Bitte melden Sie sich erneut an.", "zwei_faktor_abgelaufen");
  const k = anfrageKontext(request, ip);
  const nutzer = await sicherheit().zweiFaktorPruefen({ nutzerId: z.nutzerId, code: String(code || "").slice(0, 20), ip: k.ip, userAgent: k.userAgent, land: k.land });
  // Passwort zwischenzeitlich geändert/Konto gesperrt → Zwischenschritt ungültig
  if (!nutzer || !nutzer.aktiv || (nutzer.sitzungVersion || 0) !== z.version) throw new PlattformFehler(401, "Die Anmeldung ist abgelaufen. Bitte melden Sie sich erneut an.", "zwei_faktor_abgelaufen");
  return sitzungStarten({
    request, ip, nutzer, methode: z.methode, zweiFaktor: true, geraetMerken: !!merken,
    daten: { zweiFaktorMethode: nutzer.zweiFaktorMethode, codesUebrig: nutzer.codesUebrig },
  });
}

// src/lib/plattform/totp.js
//
// Zwei-Faktor-Anmeldung ohne Fremdpakete (nur Node-`crypto`, NUR serverseitig):
//  - TOTP nach RFC 6238 (HMAC-SHA1, 30 s, 6 Stellen) auf Basis von HOTP (RFC 4226)
//  - Base32 (RFC 4648) für den Schlüssel in Authenticator-Apps, otpauth-URI
//  - Wiederherstellungscodes (einmalig, nur als SHA-256 gespeichert)
//  - Verschlüsselung des TOTP-Schlüssels im Demo-Backend (AES-256-GCM). Frappe speichert den
//    Schlüssel in einem Password-Feld (verschlüsselt mit dem encryption_key der Site).
//
// Replay-Schutz: `totpPruefen` liefert den Zeitschritt des akzeptierten Codes; das Backend speichert
// ihn als `letzterSchritt` und akzeptiert danach nur noch spätere Schritte.

import { createCipheriv, createDecipheriv, createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";

export const PERIODE_S = 30;
export const STELLEN = 6;
/** Toleranz ± Zeitschritte (Uhrabweichung des Telefons) */
export const FENSTER = 1;
export const AUSSTELLER = "ÖkoInvest";

const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

export function base32(buf) {
  let bits = 0;
  let wert = 0;
  let out = "";
  for (const byte of buf) {
    wert = (wert << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      out += B32[(wert >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) out += B32[(wert << (5 - bits)) & 31];
  return out;
}

export function base32Lesen(s) {
  const sauber = String(s || "").toUpperCase().replace(/[\s=-]/g, "");
  let bits = 0;
  let wert = 0;
  const out = [];
  for (const z of sauber) {
    const i = B32.indexOf(z);
    if (i < 0) throw new Error("Ungültiges Base32");
    wert = (wert << 5) | i;
    bits += 5;
    if (bits >= 8) {
      out.push((wert >>> (bits - 8)) & 255);
      bits -= 8;
    }
  }
  return Buffer.from(out);
}

/** Neuer TOTP-Schlüssel: 160 Bit (Empfehlung RFC 4226), Base32 */
export const geheimnisErzeugen = () => base32(randomBytes(20));

/** HOTP-Wert (RFC 4226) für Zähler `zaehler` */
export function hotp(schluessel, zaehler, stellen = STELLEN, algo = "sha1") {
  const b = Buffer.alloc(8);
  b.writeBigUInt64BE(BigInt(zaehler));
  const h = createHmac(algo, schluessel).update(b).digest();
  const o = h[h.length - 1] & 0x0f;
  const bin = ((h[o] & 0x7f) << 24) | (h[o + 1] << 16) | (h[o + 2] << 8) | h[o + 3];
  return String(bin % 10 ** stellen).padStart(stellen, "0");
}

export const zeitschritt = (zeitMs = Date.now()) => Math.floor(zeitMs / 1000 / PERIODE_S);

/** TOTP-Code eines Base32-Schlüssels zu einem Zeitpunkt (für Tests und Anzeige) */
export const totp = (geheimnisB32, zeitMs = Date.now()) => hotp(base32Lesen(geheimnisB32), zeitschritt(zeitMs));

function gleich(a, b) {
  const x = Buffer.from(String(a));
  const y = Buffer.from(String(b));
  return x.length === y.length && timingSafeEqual(x, y);
}

/**
 * Code prüfen. Liefert den Zeitschritt des passenden Codes oder null.
 * Nur Schritte > `letzterSchritt` zählen (derselbe Code ist nie zweimal gültig).
 */
export function totpPruefen(geheimnisB32, code, { letzterSchritt = -1, zeitMs = Date.now(), fenster = FENSTER } = {}) {
  const c = String(code || "").replace(/\s/g, "");
  if (!/^\d{6}$/.test(c) || !geheimnisB32) return null;
  const schluessel = base32Lesen(geheimnisB32);
  const jetzt = zeitschritt(zeitMs);
  let treffer = null;
  // alle Fenster-Schritte rechnen (gleiche Laufzeit, unabhängig vom Treffer)
  for (let d = -fenster; d <= fenster; d++) {
    const s = jetzt + d;
    if (gleich(hotp(schluessel, s), c) && s > letzterSchritt && treffer === null) treffer = s;
  }
  return treffer;
}

/** otpauth-URI für Authenticator-Apps (Google Authenticator, Microsoft Authenticator, 1Password …) */
export function otpauthUri({ geheimnis, konto, aussteller = AUSSTELLER }) {
  const label = `${encodeURIComponent(aussteller)}:${encodeURIComponent(konto)}`;
  return `otpauth://totp/${label}?secret=${geheimnis}&issuer=${encodeURIComponent(aussteller)}&algorithm=SHA1&digits=${STELLEN}&period=${PERIODE_S}`;
}

// ---------------------------------------------------------------- Wiederherstellungscodes

const CODE_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"; // ohne 0/O/1/I
export const ANZAHL_CODES = 10;

/** Ein Code: XXXXX-XXXXX (50 Bit) */
function einCode() {
  const b = randomBytes(10);
  let s = "";
  for (let i = 0; i < 10; i++) s += CODE_ALPHABET[b[i] % 32];
  return `${s.slice(0, 5)}-${s.slice(5)}`;
}

export const codesErzeugen = (anzahl = ANZAHL_CODES) => Array.from({ length: anzahl }, einCode);
export const codeNormal = (c) => String(c || "").toUpperCase().replace(/[^0-9A-Z]/g, "");
export const codeHash = (c) => createHash("sha256").update(`oekoinvest-wiederherstellung|${codeNormal(c)}`).digest("hex");
export const istWiederherstellungscode = (c) => /^[0-9A-Z]{10}$/.test(codeNormal(c));

// ---------------------------------------------------------------- Verschlüsselung (Demo-Backend)

function schluesselMaterial() {
  const s = process.env.PLATTFORM_2FA_SCHLUESSEL || process.env.SESSION_SECRET || "";
  if (process.env.NODE_ENV === "production" && s.length < 32) {
    throw new Error("PLATTFORM_2FA_SCHLUESSEL (oder SESSION_SECRET) fehlt – in Produktion Pflicht für die Zwei-Faktor-Anmeldung.");
  }
  return createHash("sha256").update(`oekoinvest-2fa|${s || "oekoinvest-entwicklung-unsicher-nie-produktiv-verwenden"}`).digest();
}

/** Text → "v1.<iv>.<tag>.<chiffrat>" (base64url) */
export function verschluesseln(text) {
  const iv = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", schluesselMaterial(), iv);
  const ct = Buffer.concat([c.update(String(text), "utf8"), c.final()]);
  return ["v1", iv.toString("base64url"), c.getAuthTag().toString("base64url"), ct.toString("base64url")].join(".");
}

export function entschluesseln(wert) {
  const [v, iv, tag, ct] = String(wert || "").split(".");
  if (v !== "v1" || !iv || !tag || !ct) return "";
  try {
    const d = createDecipheriv("aes-256-gcm", schluesselMaterial(), Buffer.from(iv, "base64url"));
    d.setAuthTag(Buffer.from(tag, "base64url"));
    return Buffer.concat([d.update(Buffer.from(ct, "base64url")), d.final()]).toString("utf8");
  } catch {
    return "";
  }
}
