// Security-Probe (nur lokal, Demo-Backend). node sec-probe.mjs
const BASIS = "http://localhost:3100";
const LAUF = Date.now().toString(36);
const EMAIL = `sec2f-${LAUF}@example.com`;
const PW = `Probe-${LAUF}-Passwort1`;

const cookies = new Map();
function merken(res) {
  for (const sc of res.headers.getSetCookie?.() || []) {
    const [kv] = sc.split(";");
    const i = kv.indexOf("=");
    const name = kv.slice(0, i).trim();
    const wert = kv.slice(i + 1);
    if (wert === "" || /Max-Age=0/i.test(sc)) cookies.delete(name);
    else cookies.set(name, wert);
  }
}
async function anfrage(methode, pfad, body, { origin = BASIS, kopf = {} } = {}) {
  const headers = { ...kopf };
  if (origin !== null) headers.Origin = origin;
  if (cookies.size) headers.Cookie = [...cookies].map(([k, v]) => `${k}=${v}`).join("; ");
  let payload;
  if (body !== undefined) {
    headers["Content-Type"] = headers["Content-Type"] || "application/json";
    payload = typeof body === "string" ? body : JSON.stringify(body);
  }
  const res = await fetch(BASIS + pfad, { method: methode, headers, body: payload, redirect: "manual" });
  merken(res);
  let json = null;
  const text = await res.text();
  try { json = JSON.parse(text); } catch {}
  return { status: res.status, json, text, headers: res.headers };
}
let ok = 0, fehl = 0;
const p = (b, t, d) => { b ? ok++ : fehl++; console.log(`${b ? "OK " : "FEHLT"} ${t}${b ? "" : " – " + JSON.stringify(d).slice(0, 300)}`); };

// 1) Registrierung mit unerwarteten Feldern (Massenzuweisung)
let r = await anfrage("POST", "/api/auth/registrieren", {
  email: EMAIL, passwort: PW, vorname: "Sec", nachname: "Probe", rollen: ["investor"], agb: true,
  emailBestaetigt: true, aktiv: true, backofficeRollen: ["leitung"], sitzungVersion: 99, id: "U-99-HACK", passwortHash: "x",
});
p(r.status === 201 && r.json?.nutzer, "Registrierung", r);
p(r.json?.nutzer?.emailBestaetigt === false, "Massenzuweisung: emailBestaetigt nicht übernommen", r.json?.nutzer);
p(!r.json?.nutzer?.backofficeRollen, "Massenzuweisung: backofficeRollen nicht übernommen", r.json?.nutzer);
p(r.json?.nutzer?.id !== "U-99-HACK", "Massenzuweisung: id nicht übernommen", r.json?.nutzer?.id);

// 2) Registrierung mit Rolle admin
r = await anfrage("POST", "/api/auth/registrieren", { email: `sec2f-admin-${LAUF}@example.com`, passwort: PW, vorname: "A", nachname: "B", rollen: ["admin"], agb: true });
p(r.status === 422, "Rolle admin bei Registrierung abgelehnt", r);

// 3) Profil: Rollen-Eskalation
r = await anfrage("PATCH", "/api/portal/profil", { vorname: "Sec", nachname: "Probe", rollen: ["admin", "gutachter", "lieferant", "bank", "investor"] });
const rollen = r.json?.nutzer?.rollen || [];
p(r.status === 200 && !rollen.includes("admin") && !rollen.includes("gutachter") && !rollen.includes("bank"), "Profil: admin/gutachter/bank nicht selbst wählbar", rollen);

// 4) CSRF: fremde/fehlende Herkunft
r = await anfrage("PATCH", "/api/portal/profil", { vorname: "X", nachname: "Y" }, { origin: "https://evil.example" });
p(r.status === 403, "CSRF: fremder Origin → 403", r.status);
r = await anfrage("PATCH", "/api/portal/profil", { vorname: "X", nachname: "Y" }, { origin: null });
p(r.status === 403, "CSRF: ohne Origin → 403", r.status);
r = await anfrage("PATCH", "/api/portal/profil", "vorname=X", { kopf: { "Content-Type": "application/x-www-form-urlencoded" } });
p(r.status === 415, "CSRF: Formular-Content-Type → 415", r.status);

// 5) Injektion/robuste Suche
r = await anfrage("GET", `/api/portal/suche?q=${encodeURIComponent("')] OR 1=1 -- $ne (.*)+")}&limit=5`);
p(r.status === 200 && r.json?.ok, "Suche mit Sonderzeichen → 200 ohne Fehler", r);

// 6) Zu großer Body
r = await anfrage("PATCH", "/api/portal/profil", { vorname: "A".repeat(70000), nachname: "B" });
p(r.status === 413, "Body > 64 KiB → 413", r.status);

// 7) Fehlerbild: ungültiges JSON ohne Interna
r = await anfrage("PATCH", "/api/portal/profil", "{kaputt", {});
p(r.status === 400 && !/at position|SyntaxError|node_modules/i.test(r.text), "Ungültiges JSON → 400 ohne Interna", r.text.slice(0, 200));

// 8) 2FA einrichten, dann falsche Codes bei aktion "codes": zählt das zur Kontosperre?
r = await anfrage("POST", "/api/portal/sicherheit/zwei-faktor", { aktion: "starten" });
const geheimnis = r.json?.geheimnis;
p(!!geheimnis, "2FA-Einrichtung gestartet", r);
// TOTP berechnen
const { createHmac } = await import("node:crypto");
const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
function b32(s){let bits=0,w=0;const o=[];for(const z of s){w=(w<<5)|B32.indexOf(z);bits+=5;if(bits>=8){o.push((w>>>(bits-8))&255);bits-=8;}}return Buffer.from(o);}
function totp(sec){const z=Math.floor(Date.now()/30000);const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(z));const h=createHmac("sha1",b32(sec)).update(b).digest();const o=h[h.length-1]&15;return String((((h[o]&127)<<24)|(h[o+1]<<16)|(h[o+2]<<8)|h[o+3])%1e6).padStart(6,"0");}
r = await anfrage("POST", "/api/portal/sicherheit/zwei-faktor", { aktion: "bestaetigen", code: totp(geheimnis) });
p(r.status === 200 && (r.json?.codes || []).length === 10, "2FA aktiviert", r);
let gezaehlt = null;
for (let i = 0; i < 6; i++) {
  r = await anfrage("POST", "/api/portal/sicherheit/zwei-faktor", { aktion: "codes", code: "000000" });
  gezaehlt = r;
  if (r.status === 429) break;
}
// Kontosperre prüfen: Login mit richtigem Passwort
const alt = new Map(cookies); cookies.clear();
r = await anfrage("POST", "/api/auth/login", { email: EMAIL, passwort: PW });
console.log(`INFO  nach 6 falschen Codes (aktion codes): letzter Status ${gezaehlt.status}, Login danach: ${r.status} ${r.json?.code || ""}`);
for (const [k, v] of alt) cookies.set(k, v);

// 9) Sicherheits-Kopfzeilen auf /portal (mit Sitzung)
r = await anfrage("GET", "/portal/sicherheit");
p(["200","303","307","302"].includes(String(r.status)) && r.headers.get("x-frame-options") === "DENY" && r.headers.get("x-content-type-options") === "nosniff", "Portal: Sicherheitskopfzeilen", [r.status, r.headers.get("x-frame-options")]);

// 10) E-Mail-Bestätigungslink: erfundenes Token → kein Fehlerdetail, Redirect
